// Counter-proposal emails, written on this device from templates. Nothing here is
// generated by a model: each flag and rule carries `why` (one polite sentence), `better`
// (wording to propose) and `reply` (one line for the combined email), and this file fills
// them in from the clause that was flagged and from the contract's own names for the parties.

import { format } from './money.js';

export const DISCLAIMER = '[Drafted by ClauseGuard. Not legal advice: check that it fits your situation, then delete this line before you send it.]';

// The contract's own names for the client and for you, from its definitions:
// '... (the "Company")' and '... (the "Contractor")'.
const CLIENT = /^(?:company|client|customer|buyer|purchaser|agency|employer|business|brand|publisher|principal|startup)$/i;
const ME = /^(?:contractor|consultant|freelancer|service\s+provider|provider|supplier|vendor|designer|developer|engineer|writer|creator|author|artist|independent\s+contractor)$/i;

export function parties(text) {
  const out = { client: 'the Client', me: 'the Contractor' };
  let client = false, me = false;
  for (const m of text.matchAll(/\((?:hereinafter\s+(?:referred\s+to\s+as\s+)?)?(?:the\s+)?["“]([A-Z][A-Za-z ]{1,30}?)["”]\)/g)) {
    const name = m[1].trim();
    if (!client && CLIENT.test(name)) { out.client = `the ${name}`; client = true; }
    else if (!me && ME.test(name)) { out.me = `the ${name}`; me = true; }
  }
  return out;
}

const cap = (s) => s[0].toUpperCase() + s.slice(1);

/** Fills `{client}`, `{me}` and `{note}`, capitalising a name that starts a sentence. */
export function fill(s, { client, me }, note = '') {
  return s
    .replace(/(^|[.!?]\s+)\{client\}/g, (_, p) => p + cap(client))
    .replace(/(^|[.!?]\s+)\{me\}/g, (_, p) => p + cap(me))
    .replaceAll('{client}', client)
    .replaceAll('{me}', me)
    .replaceAll('{note}', note);
}

// The number a clause starts with, and the heading and sub-number that may follow it,
// as in "4. Non-Competition 4.1 During the term...".
const LEAD = /^(?:section\s+|article\s+|clause\s+)?(\(?[0-9]+(?:\.[0-9]+)*\)?|\([a-z]\))[.)]?\s+(?:(?:[A-Z][\w'-]*\s+){0,4}[A-Z][\w'-]*[.:]?\s+(\d+(?:\.\d+)+)[.)]?\s+)?/i;

/** Clause number at the start of a piece, for "section 4.1". */
export const sectionOf = (t) => { const m = t.match(LEAD); return m?.[2] ?? m?.[1]; };

/** The section clause `i` sits in: its own number, or the nearest one just before it. */
export function sectionAt(segs, i) {
  for (let j = i; j >= Math.max(0, i - 5); j--) {
    const sec = sectionOf(segs[j].text);
    if (sec) return sec;
  }
  return undefined;
}

/** A clause cut to a readable length at a word boundary, without its leading number. */
export function quote(text, max = 300) {
  const t = text.replace(LEAD, '').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  return `${cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:]$/, '')}…`;
}

// What the percentage in a flag's suggested wording comes to on this contract's fee.
const ON_FEE = {
  killfee: (f) => `At 25%, that is up to ${format(f, 0.25)} on the ${format(f)} fee.`,
  walkaway: (f) => `At 25%, that is up to ${format(f, 0.25)} on the ${format(f)} fee.`,
  nolatefee: (f) => `At 1.5% a month, an unpaid ${format(f)} would carry ${format(f, 0.015)} for each month it is late.`,
  penalty: (f) => `On the ${format(f)} fee, a 5% cap is ${format(f, 0.05)}.`,
  slowpay: (f) => `A 30% deposit on the ${format(f)} fee is ${format(f, 0.3)}.`,
  uncapped: (f) => `On this contract, that is ${format(f)}.`,
  cap: (f) => `On this contract, that is ${format(f)}.`,
};

/** One sentence putting a flag's suggested numbers in money, or '' without a fee to go on. */
export const onFee = (id, fee) => (fee && ON_FEE[id] ? ON_FEE[id](fee) : '');

/** The one-line ask for the combined email, with the section number after its heading. */
function line(item, names) {
  const sec = item.sec ?? sectionOf(item.seg);
  const reply = fill(item.f.reply, names, item.note);
  const [head, ...rest] = reply.split(': ');
  return rest.length ? `${head}${sec ? ` (section ${sec})` : ''}: ${rest.join(': ')}` : `${sec ? `Section ${sec}: ` : ''}${reply}`;
}

/**
 * One email about one flagged clause.
 * @param {{f: {why: string, better: string, reply: string}, seg: string, note?: string, sec?: string}} item
 * @param {{client: string, me: string}} names
 * @param {object} [fee]  the contract's fee, from contractFee in src/money.js
 */
export function counterProposal(item, names, fee) {
  const sec = item.sec ?? sectionOf(item.seg);
  const where = sec ? `section ${sec}` : 'this clause';
  return [
    DISCLAIMER,
    '',
    `Subject: ${sec ? `Section ${sec} of the agreement` : 'One change before I sign'}`,
    '',
    'Hi [name],',
    '',
    `Thanks for sending the agreement over. Before I sign, I'd like to suggest one change to ${where}.`,
    '',
    `It currently says: "${quote(item.seg)}"`,
    '',
    fill(item.f.why, names, item.note),
    '',
    'Would you be open to this wording instead?',
    '',
    `"${fill(item.f.better, names, item.note)}"`,
    ...(onFee(item.f.id, fee) ? ['', onFee(item.f.id, fee)] : []),
    '',
    'Happy to talk it through on a call if that is easier.',
    '',
    'Best,',
    '[your name]',
  ].join('\n');
}

/** One email covering every item, numbered, each with the wording to propose. */
export function combinedEmail(items, names, fee) {
  if (!items.length) return '';
  const body = items.map((it, i) => `${i + 1}. ${line(it, names)}\n   Suggested wording: "${fill(it.f.better, names, it.note)}"${onFee(it.f.id, fee) ? `\n   ${onFee(it.f.id, fee)}` : ''}`);
  return [
    DISCLAIMER,
    '',
    `Subject: ${items.length > 1 ? 'A few changes' : 'One change'} before I sign`,
    '',
    'Hi [name],',
    '',
    `Thanks for sending the agreement over. I'm looking forward to the project. Before I sign, I'd like to suggest ${items.length > 1 ? 'a few changes' : 'one change'}:`,
    '',
    body.join('\n\n'),
    '',
    `Happy to talk ${items.length > 1 ? 'any of these' : 'it'} through.`,
    '',
    'Best,',
    '[your name]',
  ].join('\n');
}
